<?php
declare(strict_types=1);
namespace Hls\Controllers;
use Hls\Http\HttpError; use Hls\Http\Input; use Hls\Http\View; use Hls\Repositories\Repository; use Hls\Middleware\Access; use Hls\Services\Audit;
final class EquipmentP2HController {
 public function __construct(private Repository $repo,private View $view,private Access $access,private Audit $audit){}
 public function handle():void {
  $this->access->demand('equipment.p2h.view'); $mode=Input::text($_GET,'mode',10,false)?:'list'; if(!in_array($mode,['list','create','detail','print'],true))throw new HttpError(404,'Halaman tidak tersedia.'); $id=Input::id($_GET,'id',true);$error=null;
  if($_SERVER['REQUEST_METHOD']==='POST'){ $action=Input::text($_POST,'action',12);$this->access->demand($action==='save'?'equipment.p2h.create':'equipment.p2h.review');$branch=Input::id($_POST,'branch_id');$this->access->demandBranch($branch);$key=Input::text($_POST,'request_key',64);$this->repo->db->beginTransaction();try{if($action==='save'){$asset=Input::id($_POST,'asset_id');$date=Input::text($_POST,'inspected_at',19);$shift=Input::text($_POST,'shift',40,false);$items=$_POST['items']??[];if(!is_array($items)||!$items)throw new HttpError(422,'Checklist wajib diisi.');$critical=0;foreach($items as $code=>$item){$result=Input::text($item,'result',14);$sev=Input::text($item,'severity',8,false);$note=Input::text($item,'note',2000,false);if(!in_array($result,['BAIK','RUSAK','TIDAK_BERLAKU'],true)||($result==='RUSAK'&&$note===''))throw new HttpError(422,'Hasil checklist atau catatan rusak tidak valid.');if($result==='RUSAK'&&$sev==='CRITICAL')$critical=1;}$this->repo->run('INSERT INTO eq_p2h_inspections(internal_ref,branch_id,asset_id,operator_id,inspected_at,shift,location,meter_type,meter_reading,status,fitness_status,general_note,critical_finding,created_by) VALUES(?,?,?,?,?,?,?,?,?,"DRAFT",NULL,?,?,?)',['P2H-'.strtoupper(bin2hex(random_bytes(8))),$branch,$asset,Input::id($_POST,'operator_id',true)?:null,$date,$shift,Input::text($_POST,'location',255,false),Input::text($_POST,'meter_type',3),Input::text($_POST,'meter_reading',20,false)===''?null:(float)$_POST['meter_reading'],Input::text($_POST,'general_note',2000,false),$critical,$this->access->user['id']]);$id=(int)$this->repo->db->lastInsertId();foreach($items as $code=>$item)$this->repo->run('INSERT INTO eq_p2h_items(inspection_id,category,item_code,item_label,result,severity,note,follow_up) VALUES(?,?,?,?,?,?,?,?)',[$id,Input::text($item,'category',80),$code,Input::text($item,'label',255),Input::text($item,'result',14),Input::text($item,'severity',8,false)?:null,Input::text($item,'note',2000,false),Input::flag($item,'follow_up')]);$this->audit->record((int)$this->access->user['id'],'equipment_p2h_created','eq_p2h_inspections',$id,['critical'=>$critical]);}elseif($action==='submit'){$id=Input::id($_POST,'id');$this->repo->run("UPDATE eq_p2h_inspections SET status='SUBMITTED',version=version+1 WHERE id=? AND status='DRAFT'",[$id]);$this->audit->record((int)$this->access->user['id'],'equipment_p2h_submitted','eq_p2h_inspections',$id,[]);}elseif($action==='review'){$id=Input::id($_POST,'id');$fitness=Input::text($_POST,'fitness_status',16);if(!in_array($fitness,['FIT_FOR_OPERATION','FIT_WITH_NOTES','HOLD'],true))throw new HttpError(422,'Hasil kelayakan tidak valid.');$row=$this->repo->one('SELECT * FROM eq_p2h_inspections WHERE id=? FOR UPDATE',[$id]);if(!$row||$row['status']!=='SUBMITTED')throw new HttpError(409,'P2H tidak siap direview.');$this->repo->one('SELECT id FROM md_assets WHERE id=? FOR UPDATE',[$row['asset_id']]);if((int)$row['critical_finding']===1&&$fitness!=='HOLD')throw new HttpError(422,'Temuan critical wajib HOLD.');$this->repo->run("UPDATE eq_p2h_inspections SET status='REVIEWED',fitness_status=?,reviewed_by=?,reviewed_at=NOW(),version=version+1 WHERE id=?",[$fitness,$this->access->user['id'],$id]);if($fitness==='HOLD'){$this->repo->run('INSERT INTO eq_unit_holds(asset_id,branch_id,source_p2h_id,reason,activated_by,activated_at) SELECT asset_id,branch_id,id,COALESCE(general_note,"Temuan P2H HOLD"),?,NOW() FROM eq_p2h_inspections WHERE id=? ON DUPLICATE KEY UPDATE reason=VALUES(reason)',[$this->access->user['id'],$id]);}$this->audit->record((int)$this->access->user['id'],'equipment_p2h_reviewed','eq_p2h_inspections',$id,['fitness'=>$fitness]);}$this->repo->db->commit();$this->view->redirect('/maintenance/p2h?mode=detail&id='.$id);}catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();if($e instanceof HttpError)throw $e;throw $e;}}
  $rows=$this->repo->all('SELECT p.*,b.name branch_name,a.code asset_code,a.name asset_name FROM eq_p2h_inspections p JOIN branches b ON b.id=p.branch_id JOIN md_assets a ON a.id=p.asset_id WHERE p.branch_id IN (SELECT branch_id FROM user_branches WHERE user_id=? UNION SELECT id FROM branches WHERE ?=1) ORDER BY p.id DESC',[$this->access->user['id'],$this->access->user['all_branches']]);$row=$id?$this->repo->one('SELECT p.*,b.name branch_name,a.code asset_code,a.name asset_name FROM eq_p2h_inspections p JOIN branches b ON b.id=p.branch_id JOIN md_assets a ON a.id=p.asset_id WHERE p.id=?',[$id]):null;$items=$id?$this->repo->all('SELECT * FROM eq_p2h_items WHERE inspection_id=? ORDER BY id',[$id]):[];$holds=($row&&$this->repo->one('SELECT id FROM eq_unit_holds WHERE source_p2h_id=? LIMIT 1',[$id]))?$this->repo->all('SELECT h.*,u.name activated_name,r.name released_name FROM eq_unit_holds h JOIN users u ON u.id=h.activated_by LEFT JOIN users r ON r.id=h.released_by WHERE h.source_p2h_id=? ORDER BY h.id DESC',[$id]):[];$assets=$this->repo->all('SELECT id,code,name,branch_id FROM md_assets WHERE active=1 ORDER BY code');$this->view->render('equipment-p2h',compact('mode','rows','row','items','holds','assets','error'));
 }
 public function release():void { $this->access->demand('equipment.p2h.hold.release'); $id=Input::id($_POST,'hold_id'); $reason=Input::text($_POST,'release_reason',2000); if($reason==='') throw new HttpError(422,'Alasan release wajib.'); $this->access->demandBranch(Input::id($_POST,'branch_id')); $this->repo->db->beginTransaction(); try { $h=$this->repo->one('SELECT * FROM eq_unit_holds WHERE id=? FOR UPDATE',[$id]); if(!$h||$h['released_at']!==null) throw new HttpError(409,'HOLD sudah dilepas atau tidak ditemukan.'); $this->repo->run('UPDATE eq_unit_holds SET released_by=?,released_at=NOW(),release_reason=?,version=version+1 WHERE id=? AND released_at IS NULL',[$this->access->user['id'],$reason,$id]); $this->audit->record((int)$this->access->user['id'],'equipment_p2h_hold_released','eq_unit_holds',$id,['reason'=>$reason]); $this->repo->db->commit(); $this->view->redirect('/maintenance/p2h?mode=detail&id='.$h['source_p2h_id']); } catch(\Throwable $e){if($this->repo->db->inTransaction())$this->repo->db->rollBack();throw $e;} }
}